// Generated by vibelang from src/workspaces/inventory.ts; the migrate flow writes it again with each batch.
import { sameDirectory } from "@opencode/util/path";
export function worktreeInventoryKey(scope, projectID) {
    return [scope, "worktree", projectID];
}
export function worktreeInventoryViewKey(scope, projectID) {
    return [scope, "settings-workspace-inventory", projectID ?? null];
}
// Project metadata arrives without worktrees; a loaded inventory supplies the workspace list.
export function withWorktreeInventory(project, worktrees) {
    if (!worktrees)
        return project;
    return {
        ...project,
        worktrees: [...worktrees],
        sandboxes: worktrees
            .map((item) => item.directory)
            .filter((directory) => !sameDirectory(project.worktree, directory)),
    };
}
// Reads use saved inventory; explicit demand also discovers external worktree changes.
export function createWorktreeInventory(input) {
    const options = (projectID) => ({
        queryKey: worktreeInventoryKey(input.scope, projectID),
        queryFn: () => input
            .api()
            .list({ projectID })
            .then((items) => {
            input.updated(projectID, items);
            return items;
        }),
        // `worktree.updated` and reconnect invalidation drive list reloads; time alone does not re-list.
        staleTime: Infinity,
        gcTime: Infinity,
        retry: false,
    });
    return {
        cached: (projectID) => input.queryClient.getQueryData(worktreeInventoryKey(input.scope, projectID)),
        list: (projectID) => input.queryClient.fetchQuery({ ...options(projectID), staleTime: 0 }).catch(() => undefined),
        refresh: (projectID) => input
            .api()
            .refresh({ projectID })
            .catch(() => undefined),
    };
}
